const portfolioItems=[{id:'essay1',category:'essay',icon:'📝',badge:'Essay',grade:'A+',title:'Essay Ekonomi Mikro',img:'essay-ekonomi-mikro.jpg',desc:'Analisis tentang teori permintaan dan penawaran dalam pasar kompetitif.',meta:['📄 15 Halaman','⏱️ 3 Hari','📚 Ekonomi'],client:'👨‍🎓',name:'Budi S.',univ:'Mahasiswa UI'},{id:'skripsi1',category:'skripsi',icon:'🎓',badge:'Skripsi',grade:'A',title:'Skripsi Manajemen SDM',img:'skripsi-manajemen-sdm.jpg',desc:'Penelitian kuantitatif tentang pengaruh motivasi kerja terhadap produktivitas.',meta:['📄 85 Halaman','⏱️ 30 Hari','📚 Manajemen'],client:'👩‍🎓',name:'Sarah P.',univ:'Mahasiswa UGM'},{id:'prog1',category:'programming',icon:'💻',badge:'Programming',grade:'95',title:'Sistem Inventory Python',img:'sistem-inventory-python.jpg',desc:'Aplikasi manajemen inventory berbasis Python dengan GUI dan SQLite.',meta:['💻 Python','⏱️ 7 Hari','📦 500+LOC'],client:'👨‍💻',name:'Ahmad R.',univ:'Mahasiswa ITB'},{id:'analisis1',category:'analisis',icon:'📊',badge:'Analisis Data',grade:'A+',title:'Analisis Regresi SPSS',img:'analisis-regresi-spss.jpg',desc:'Analisis regresi linear berganda untuk penelitian marketing mix.',meta:['📊 SPSS','⏱️ 5 Hari','📈 Output Lengkap'],client:'👩‍💼',name:'Dewi K.',univ:'Mahasiswa UNPAD'},{id:'desain1',category:'desain',icon:'🎨',badge:'Desain',grade:'A',title:'Presentasi Bisnis Modern',img:'presentasi-bisnis-modern.jpg',desc:'PowerPoint profesional dengan desain modern untuk business plan.',meta:['🎨 PowerPoint','⏱️ 2 Hari','📑 25 Slides'],client:'👨‍💼',name:'Rizky M.',univ:'Mahasiswa BINUS'},{id:'prog2',category:'programming',icon:'🌐',badge:'Programming',grade:'A+',title:'Website E-Commerce',img:'website-e-commerce.jpg',desc:'Website toko online dengan PHP & MySQL. Fitur cart,checkout,admin panel.',meta:['💻 PHP & MySQL','⏱️ 14 Hari','🛒 Full Stack'],client:'👩‍💻',name:'Lisa A.',univ:'Mahasiswa Telkom'},{id:'essay2',category:'essay',icon:'📄',badge:'Makalah',grade:'A',title:'Makalah Hukum Perdata',img:'makalah-hukum-perdata.jpg',desc:'Analisis tentang perjanjian jual beli dalam perspektif KUHPerdata.',meta:['📄 20 Halaman','⏱️ 5 Hari','⚖️ Hukum'],client:'👨‍⚖️',name:'Andi W.',univ:'Mahasiswa UNAIR'},{id:'skripsi2',category:'skripsi',icon:'📖',badge:'Skripsi',grade:'A',title:'Skripsi Akuntansi',img:'skripsi-akuntansi.jpg',desc:'Penelitian GCG terhadap nilai perusahaan pada perusahaan LQ45.',meta:['📄 90 Halaman','⏱️ 45 Hari','💹 Akuntansi'],client:'👩‍🎓',name:'Maya S.',univ:'Mahasiswa Trisakti'},{id:'analisis2',category:'analisis',icon:'📈',badge:'Analisis Data',grade:'98',title:'SEM-PLS Analysis',img:'sem-pls-analysis.jpg',desc:'Analisis Structural Equation Modeling menggunakan SmartPLS.',meta:['📊 SmartPLS','⏱️ 7 Hari','📈 Full Report'],client:'👨‍🔬',name:'Fajar H.',univ:'Mahasiswa UB'}];const portfolioDetails={essay1:{title:'Essay Ekonomi Mikro',icon:'📝',category:'Essay',grade:'A+',desc:'Analisis mendalam tentang teori permintaan dan penawaran dalam pasar kompetitif.',specs:['📄 15 halaman','⏱️ 3 hari','📚 Format APA 7th','📖 20+jurnal','✅ Plagiarisme<10%'],result:'Nilai A+dengan pujian dari dosen.'},skripsi1:{title:'Skripsi Manajemen SDM',icon:'🎓',category:'Skripsi',grade:'A',desc:'Penelitian kuantitatif dengan sampel 150 responden dari 5 perusahaan.',specs:['📄 85 halaman','⏱️ 30 hari','📊 SPSS Regresi','📖 50+sumber','✅ Revisi Unlimited'],result:'Lulus sidang dengan nilai A.'},prog1:{title:'Sistem Inventory Python',icon:'💻',category:'Programming',grade:'95',desc:'Aplikasi desktop manajemen stok dengan Tkinter dan SQLite.',specs:['✅ CRUD lengkap','✅ Laporan PDF','✅ Export Excel','✅ Notifikasi stok','💻 Python 3.10'],result:'Nilai 95/100.'},analisis1:{title:'Analisis Regresi SPSS',icon:'📊',category:'Analisis Data',grade:'A+',desc:'Analisis data kuantitatif untuk skripsi manajemen pemasaran.',specs:['📊 Uji Validitas','📊 Uji Asumsi Klasik','📊 Regresi Berganda','📊 Uji t dan F','📊 Koef. Determinasi'],result:'Diterima tanpa revisi.'},desain1:{title:'Presentasi Bisnis Modern',icon:'🎨',category:'Desain',grade:'A',desc:'Desain PowerPoint modern minimalis untuk presentasi Kewirausahaan.',specs:['📑 25 slides','🎨 Modern design','✏️ 100% editable','📊 Custom charts','🖼️ UI mockup'],result:'Menjadi contoh untuk mahasiswa lain.'},prog2:{title:'Website E-Commerce',icon:'🌐',category:'Programming',grade:'A+',desc:'Website e-commerce fully functional dengan PHP & MySQL.',specs:['🛒 Cart & checkout','👤 User auth','💳 Payment mock','📦 Order tracking','🔧 Admin panel'],result:'Nilai A+dan dijadikan contoh proyek.'},essay2:{title:'Makalah Hukum Perdata',icon:'📄',category:'Makalah',grade:'A',desc:'Analisis hukum perjanjian jual beli dengan studi kasus putusan.',specs:['📄 20 halaman','⏱️ 5 hari','📚 UU & Putusan MA','✅ Plagiarisme<12%'],result:'Nilai A dengan apresiasi.'},skripsi2:{title:'Skripsi Akuntansi',icon:'📖',category:'Skripsi',grade:'A',desc:'Skripsi kuantitatif dengan analisis data panel menggunakan EViews.',specs:['📄 90 halaman','⏱️ 45 hari','📊 EViews Panel','📖 60+sumber','🏢 35 perusahaan'],result:'Predikat cumlaude.'},analisis2:{title:'SEM-PLS Analysis',icon:'📈',category:'Analisis Data',grade:'98',desc:'Analisis SEM dengan SmartPLS untuk penelitian konsumen online.',specs:['📊 Outer & Inner Model','📊 Bootstrapping','📊 Mediating Effect','📊 Moderating Effect'],result:'Nilai 98/100,publikasi jurnal.'}};function renderPortfolio(filter='all'){const grid=document.getElementById('portfolioGrid');if(!grid)return;const filtered=filter==='all'?portfolioItems:portfolioItems.filter(item=>item.category===filter);grid.innerHTML=filtered.map(item=>`<div class="portfolio-card" data-category="${item.category}"><div class="portfolio-image" data-category="${item.category}"><img src="assets/images/${item.img}" alt="${item.title}" loading="lazy" class="portfolio-img"></div><div class="portfolio-content"><h3>${item.title}</h3><p>${item.desc}</p><div class="portfolio-meta">${item.meta.map(m=>`<span>${m}</span>`).join('')}</div><div class="portfolio-footer"><div class="portfolio-client"><div class="client-avatar">${item.client}</div><div class="client-info"><strong>${item.name}</strong><span>${item.univ}</span></div></div><button class="btn btn-outline btn-sm" onclick="showPortfolioDetail('${item.id}')">Lihat Detail</button></div></div></div>`).join('');}document.querySelectorAll('.filter-btn').forEach(btn=>{btn.addEventListener('click',()=>{document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderPortfolio(btn.dataset.filter);});});function showPortfolioDetail(id){const data=portfolioDetails[id];const item=portfolioItems.find(i=>i.id===id);if(!data ||!item)return;document.getElementById('lightboxTitle').textContent=data.title;document.getElementById('lightboxBody').innerHTML=`<div class="lightbox-preview"><img src="assets/images/${item.img}" alt="${data.title}" class="lightbox-img"></div><div style="margin-bottom:1rem;"><span style="background:rgba(139,92,246,0.2);color:var(--primary);padding:0.5rem 1rem;border-radius:20px;">${data.category}</span><span style="background:rgba(34,197,94,0.2);color:#22c55e;padding:0.5rem 1rem;border-radius:20px;margin-left:0.5rem;">⭐ ${data.grade}</span></div><p style="color:var(--text-secondary);margin-bottom:1.5rem;">${data.desc}</p><h4>Spesifikasi</h4><ul>${data.specs.map(s=>`<li>${s}</li>`).join('')}</ul><h4>Hasil</h4><p style="color:#22c55e;">✨ ${data.result}</p><div style="margin-top:1.5rem;padding-top:1.5rem;border-top:1px solid var(--glass-border);"><a href="kontak.html" class="btn btn-primary">Pesan Layanan Serupa</a></div>`;document.getElementById('portfolioLightbox').classList.add('active');}function closeLightbox(){document.getElementById('portfolioLightbox').classList.remove('active');}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLightbox();});document.getElementById('portfolioLightbox')?.addEventListener('click',e=>{if(e.target.id==='portfolioLightbox')closeLightbox();});document.addEventListener('DOMContentLoaded',()=>renderPortfolio());